import { getUrlByFormat } from '@/utils/upload/urlBuilder';
const IMAGE_EXTENSIONS = ['jpg', 'jpeg', 'png', 'gif', 'bmp', 'webp', 'svg', 'tiff', 'ico', 'avif', 'heic', 'jfif', 'pjpeg', 'pjp', 'raw', 'cr2', 'nef', 'dng', 'eps', 'ai', 'emf', 'wmf'];
const VIDEO_EXTENSIONS = ['mp4', 'webm', 'ogg', 'mkv'];
const FORMAT_LABELS = {
  url: 'URL',
  md: 'MD',
  html: 'HTML',
  ubb: 'BB'
};
export default {
  name: 'UploadFileItem',
  props: {
    file: {
      type: Object,
      required: true
    },
    format: {
      type: String,
      default: 'url'
    }
  },
  emits: ['copy', 'remove', 'preview-error'],
  computed: {
    statusKey() {
      const status = this.file.status;
      if (status === 'success' || status === 'done') return 'done';
      if (status === 'waiting') return 'waiting';
      if (status === 'exception') return 'exception';
      return 'uploading';
    },
    isDone() {
      return this.statusKey === 'done';
    },
    progressText() {
      const percent = Number(this.file.progreess) || 0;
      return `${Math.min(100, Math.max(0, Math.round(percent)))}%`;
    },
    barWidth() {
      if (this.statusKey === 'exception') return '100%';
      const percent = Number(this.file.progreess) || 0;
      return `${Math.min(100, Math.max(0, percent))}%`;
    },
    formatLabel() {
      return FORMAT_LABELS[this.format] || 'URL';
    },
    linkValue() {
      return getUrlByFormat(this.file, this.format);
    },
    nameParts() {
      const name = this.file.name || '';
      const dotIndex = name.lastIndexOf('.');
      const ext = dotIndex > 0 ? name.slice(dotIndex) : '';
      const base = dotIndex > 0 ? name.slice(0, dotIndex) : name;
      const tail = base.slice(-4);
      return {
        start: base.slice(0, Math.max(0, base.length - tail.length)),
        end: tail + ext
      };
    }
  },
  methods: {
    isImage(fileName) {
      const ext = fileName.split('.').pop().toLowerCase();
      return IMAGE_EXTENSIONS.includes(ext);
    },
    isVideo(fileName) {
      const ext = fileName.split('.').pop().toLowerCase();
      return VIDEO_EXTENSIONS.includes(ext);
    },
    selectAllText(event) {
      event.target.select();
      navigator.clipboard.writeText(event.target.value).then(() => {
        this.$message({
          type: 'success',
          message: this.$t('uploadForm.copySuccess')
        });
      }).catch(() => {
        this.$message({
          type: 'error',
          message: this.$t('uploadForm.copyFailed')
        });
      });
    }
  }
};